-- Warranty reporting indexes. Apply after V20260717_06. Test environment only.
CREATE INDEX IF NOT EXISTS idx_warranty_reports_marked_result ON warranty_claims(marked_warranty_at,result);CREATE INDEX IF NOT EXISTS idx_warranty_reports_resolved_result ON warranty_claims(resolved_at,result) WHERE resolved_at IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_warranty_reports_complaint_registered ON warranty_claims(complaint_registered_date) WHERE complaint_registered_date IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_warranty_reports_actual_visit ON warranty_claims(actual_visit_date) WHERE actual_visit_date IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_warranty_reports_rejected ON warranty_claims(warranty_rejected_at) WHERE warranty_rejected_at IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_warranty_reports_replacement_approved ON warranty_claims(replacement_approved_at) WHERE replacement_approved_at IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_warranty_reports_replacement_received ON warranty_replacements(replacement_received_date) WHERE replacement_received_date IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_warranty_reports_replacement_delivered ON warranty_replacements(replacement_given_to_customer_date) WHERE replacement_given_to_customer_date IS NOT NULL;
